import { useState, useEffect, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { useConnectivity } from "../../hooks/useConnectivity";
import AddIcon from "@mui/icons-material/Add";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import PersonAddIcon from "@mui/icons-material/PersonAdd";
import RemoveCircleOutlineRoundedIcon from "@mui/icons-material/RemoveCircleOutlineRounded";
import PeopleIcon from "@mui/icons-material/People";
import SearchIcon from "@mui/icons-material/Search";
import CloseIcon from "@mui/icons-material/Close";
import EventNote from "@mui/icons-material/EventNote";
import RouteIcon from "@mui/icons-material/Route";
import ConfirmDialog from "../../components/shared/ConfirmDialog";
import EmptyState from "../../components/shared/EmptyState";
import {
    getProgrammes, createProgramme, updateProgramme, deleteProgramme,
    getRoutes, addRoute, updateRoute, deleteRoute,
    getDelegates, addDelegate, removeDelegate, setDelegateRoutes,
    getUsers,
} from "../../services/api";

function RouteManageModal({ route, allDelegates, programmeId, onClose, onSaved }) {
    const [selectedIds, setSelectedIds] = useState([]);
    const [saving, setSaving] = useState(false);
    const [search, setSearch] = useState("");

    useEffect(() => {
        if (route) {
            setSelectedIds(
                allDelegates.filter((d) => d.routeIds?.includes(route.id)).map((d) => d.id)
            );
        }
    }, [route, allDelegates]);

    const { onRoute, unassigned, otherRoutes } = useMemo(() => {
        const onR = [], un = [], other = [];
        for (const d of allDelegates) {
            const isOnThisRoute = d.routeIds?.includes(route.id);
            const hasOtherRoute = d.routeIds?.length > 0 && !isOnThisRoute;
            const match = !search.trim() || d.name.toLowerCase().includes(search.toLowerCase());
            if (!match) continue;
            if (isOnThisRoute) onR.push(d);
            else if (hasOtherRoute) other.push(d);
            else un.push(d);
        }
        return { onRoute: onR, unassigned: un, otherRoutes: other };
    }, [allDelegates, route, search]);

    if (!route) return null;

    const handleToggle = (id) => {
        setSelectedIds((prev) => prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]);
    };

    const handleSave = async () => {
        setSaving(true);
        try {
            for (const d of allDelegates) {
                const was = d.routeIds?.includes(route.id);
                const now = selectedIds.includes(d.id);
                if (was === now) continue;
                await setDelegateRoutes(programmeId, d.id, now ? [route.id] : []);
            }
            onSaved();
            onClose();
        } catch (e) {
            // ignore
        } finally {
            setSaving(false);
        }
    };

    const renderDelegate = (d, showRouteName) => {
        const checked = selectedIds.includes(d.id);
        const otherRoute = d.routeNames?.find((n) => n !== route.name) || d.routeName;
        return (
            <label key={d.id} className={`flex items-center gap-3 px-3 py-2.5 rounded-xl cursor-pointer transition-colors ${checked ? "bg-accent/10" : "hover:bg-white/5"}`}>
                <input type="checkbox" className="accent-accent h-4 w-4 shrink-0" checked={checked} onChange={() => handleToggle(d.id)} />
                <div className="avatar avatar-sm avatar-neutral">{d.name.charAt(0)}</div>
                <div className="min-w-0 flex-1">
                    <div className="row-title truncate">{d.name}</div>
                    {showRouteName && otherRoute && (
                        <div className="text-[11px] text-muted truncate">Currently on <span className="font-medium text-ink">{otherRoute}</span></div>
                    )}
                </div>
                {checked && <span className="pill pill-accent shrink-0">Selected</span>}
            </label>
        );
    };

    const totalCount = allDelegates.length;
    const filteredCount = onRoute.length + unassigned.length + otherRoutes.length;

    return (
        <div className="sheet-backdrop" onClick={onClose}>
            <div className="sheet" onClick={(e) => e.stopPropagation()}>
                <div className="sheet-handle" />
                <div className="sheet-header">
                    <div className="min-w-0 flex-1">
                        <h3 className="sheet-title">{route.name}</h3>
                        <p className="sheet-sub">{selectedIds.length} of {totalCount} delegates</p>
                    </div>
                    <button className="sheet-close" onClick={onClose}>
                        <CloseIcon />
                    </button>
                </div>

                <div className="px-5 pt-2 pb-2 shrink-0">
                    <div className="search-box">
                        <SearchIcon className="search-icon" />
                        <input
                            type="text"
                            placeholder="Search delegates..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            className="search-input"
                        />
                        {search && (
                            <button className="search-clear" onClick={() => setSearch("")}>
                                <CloseIcon />
                            </button>
                        )}
                    </div>
                </div>

                <div className="sheet-body space-y-3">
                    {filteredCount === 0 ? (
                        <p className="text-xs text-muted text-center py-8">No delegates match your search.</p>
                    ) : (
                        <>
                            {onRoute.length > 0 && (
                                <div>
                                    <div className="flex items-center justify-between px-1 py-1.5">
                                        <span className="text-[11px] font-semibold text-muted uppercase tracking-wide">On this route</span>
                                        <span className="text-[10px] text-muted">{onRoute.length}</span>
                                    </div>
                                    <div className="space-y-0.5">{onRoute.map((d) => renderDelegate(d, false))}</div>
                                </div>
                            )}
                            {unassigned.length > 0 && (
                                <div>
                                    <div className="flex items-center justify-between px-1 py-1.5">
                                        <span className="text-[11px] font-semibold text-muted uppercase tracking-wide">Unassigned</span>
                                        <span className="text-[10px] text-muted">{unassigned.length}</span>
                                    </div>
                                    <div className="space-y-0.5">{unassigned.map((d) => renderDelegate(d, false))}</div>
                                </div>
                            )}
                            {otherRoutes.length > 0 && (
                                <div>
                                    <div className="flex items-center justify-between px-1 py-1.5">
                                        <span className="text-[11px] font-semibold text-warn uppercase tracking-wide">On other routes</span>
                                        <span className="text-[10px] text-muted">{otherRoutes.length}</span>
                                    </div>
                                    <div className="space-y-0.5">{otherRoutes.map((d) => renderDelegate(d, true))}</div>
                                </div>
                            )}
                        </>
                    )}
                </div>

                <div className="sheet-footer">
                    <button className="btn btn-primary flex-1 py-3" onClick={handleSave} disabled={saving}>
                        {saving ? "Saving..." : `Save (${selectedIds.length})`}
                    </button>
                    <button className="btn btn-secondary px-6 py-3" onClick={onClose}>Cancel</button>
                </div>
            </div>
        </div>
    );
}

function DelegateRow({ d, onRemove }) {
    return (
        <div className="row rounded-xl bg-surface-2 border border-edge">
            <div className="row-left">
                <div className="avatar avatar-sm avatar-neutral">
                    {d.name.charAt(0)}
                </div>
                <div className="row-text">
                    <div className="flex items-center gap-2">
                        <span className="row-title">{d.name}</span>
                        {d.badge && <span className="meta">{d.badge}</span>}
                    </div>
                    {d.routeName && (
                        <div className="flex flex-wrap gap-1 mt-1">
                            <span className="pill pill-accent">{d.routeName}</span>
                        </div>
                    )}
                </div>
            </div>
            <button className="btn btn-icon text-bad hover:bg-bad-dim" onClick={() => onRemove(d.id)} title="Remove from programme">
                <RemoveCircleOutlineRoundedIcon />
            </button>
        </div>
    );
}

function UserPicker({ users, alreadyAdded, onAdd, onCancel, routes }) {
    const [selectedIds, setSelectedIds] = useState([]);
    const [adding, setAdding] = useState(false);
    const [assignRouteId, setAssignRouteId] = useState(routes.length === 1 ? routes[0].id : "");

    const available = users.filter((u) => !alreadyAdded(u.id));

    const handleSubmit = async () => {
        if (!selectedIds.length) return;
        setAdding(true);
        try {
            await onAdd(selectedIds, assignRouteId || undefined);
        } finally {
            setAdding(false);
        }
    };

    return (
        <div className="rounded-xl bg-surface-2 border border-edge p-3 space-y-2">
            <div className="flex items-center justify-between">
                <span className="text-xs font-semibold text-accent">Add from user list</span>
                {selectedIds.length > 0 && (
                    <span className="text-[11px] text-muted">{selectedIds.length} selected</span>
                )}
            </div>
            <div className="max-h-48 overflow-y-auto space-y-1">
                {available.length === 0 ? (
                    <p className="text-xs text-muted text-center py-4">All users are already added.</p>
                ) : (
                    available.map((u) => {
                        const checked = selectedIds.includes(u.id);
                        return (
                            <label key={u.id} className={`flex items-center gap-2 p-2.5 rounded-lg cursor-pointer transition-colors ${checked ? "bg-accent/10" : "hover:bg-white/5"}`}>
                                <input type="checkbox" className="accent-accent h-4 w-4 shrink-0" checked={checked} onChange={() => setSelectedIds((prev) => checked ? prev.filter((i) => i !== u.id) : [...prev, u.id])} />
                                <div className="avatar avatar-sm avatar-accent">
                                    {u.enName.charAt(0)}
                                </div>
                                <span className="text-xs font-medium text-ink truncate min-w-0">{u.enName}</span>
                                {u.zhName && <span className="text-[10px] text-muted shrink-0">{u.zhName}</span>}
                            </label>
                        );
                    })
                )}
            </div>
            {routes.length > 0 && (
                <select className="select py-2" value={assignRouteId} onChange={(e) => setAssignRouteId(e.target.value)}>
                    <option value="">No route assignment</option>
                    {routes.map((r) => (
                        <option key={r.id} value={r.id}>{r.name}</option>
                    ))}
                </select>
            )}
            <div className="flex gap-2 pt-1">
                <button className="btn btn-primary flex-1" onClick={handleSubmit} disabled={!selectedIds.length || adding}>
                    {adding ? "Adding..." : `Add (${selectedIds.length})`}
                </button>
                <button className="btn btn-secondary flex-1" onClick={onCancel}>Cancel</button>
            </div>
        </div>
    );
}

function getAuthUser() {
    const raw = localStorage.getItem('authUser');
    if (!raw) return null;
    try {
        return JSON.parse(raw);
    } catch {
        return null;
    }
}

export default function ProgrammePage() {
    const navigate = useNavigate();
    const currentUser = getAuthUser();

    if (!currentUser) {
        navigate('/login');
        return null;
    }

    const [programmes, setProgrammes] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const [showForm, setShowForm] = useState(false);
    const [editing, setEditing] = useState(null);
    const [formName, setFormName] = useState("");
    const [formStart, setFormStart] = useState("");
    const [formEnd, setFormEnd] = useState("");

    const [expandedId, setExpandedId] = useState(null);
    const [routes, setRoutes] = useState([]);
    const [routesLoading, setRoutesLoading] = useState(false);
    const [newRouteName, setNewRouteName] = useState("");
    const [editingRouteId, setEditingRouteId] = useState(null);
    const [editingRouteName, setEditingRouteName] = useState("");

    const [delegates, setDelegates] = useState([]);
    const [delegatesLoading, setDelegatesLoading] = useState(false);
    const [showAddDelegate, setShowAddDelegate] = useState(false);
    const [allUsers, setAllUsers] = useState([]);
    const [usersLoading, setUsersLoading] = useState(false);

    const [manageRoute, setManageRoute] = useState(null);

    const [confirmDelete, setConfirmDelete] = useState(null);
    const [confirmDeleteRoute, setConfirmDeleteRoute] = useState(null);
    const [confirmRemoveDelegate, setConfirmRemoveDelegate] = useState(null);

    const { isOnline } = useConnectivity();

    const loadProgrammes = () => {
        setLoading(true);
        getProgrammes().then((data) => setProgrammes(data || [])).catch((e) => setError(e.message)).finally(() => setLoading(false));
    };

    useEffect(() => { loadProgrammes(); }, []);

    useEffect(() => {
        loadProgrammes();
    }, [isOnline]);

    useEffect(() => {
        const onSyncDone = () => {
            loadProgrammes();
            if (expandedId) loadDelegates(expandedId);
        };
        window.addEventListener('sync:done', onSyncDone);
        return () => window.removeEventListener('sync:done', onSyncDone);
    }, [expandedId]);

    const loadDelegates = async (id) => {
        setDelegatesLoading(true);
        try {
            const data = await getDelegates(id);
            setDelegates(data || []);
        } catch (e) {
            setError(e.message);
        } finally {
            setDelegatesLoading(false);
        }
    };

    const openCreate = () => {
        setEditing(null);
        setFormName(""); setFormStart(""); setFormEnd("");
        setShowForm(true);
    };

    const openEdit = (p) => {
        setEditing(p.id);
        setFormName(p.name); setFormStart(p.startDate); setFormEnd(p.endDate);
        setShowForm(true);
    };

    const handleSave = async () => {
        if (!formName.trim() || !formStart || !formEnd) return;
        try {
            if (editing) {
                await updateProgramme(editing, { name: formName, startDate: formStart, endDate: formEnd });
                if (!navigator.onLine) {
                    setProgrammes(prev => prev.map(p =>
                        p.id === editing ? { ...p, name: formName, startDate: formStart, endDate: formEnd } : p
                    ));
                }
            } else {
                const created = await createProgramme({ name: formName, startDate: formStart, endDate: formEnd });
                if (!navigator.onLine) {
                    setProgrammes(prev => [...prev, { ...created, id: 'pending-' + Date.now() }]);
                }
            }
            setShowForm(false);
            if (navigator.onLine) loadProgrammes();
        } catch (e) { setError(e.message); }
    };

    const handleDelete = async (id) => {
        try {
            await deleteProgramme(id);
            if (expandedId === id) { setExpandedId(null); setRoutes([]); }
            if (navigator.onLine) {
                loadProgrammes();
            } else {
                setProgrammes(prev => prev.filter(p => p.id !== id));
            }
        } catch (e) { setError(e.message); }
    };

    const toggleExpand = async (id) => {
        if (expandedId === id) {
            setExpandedId(null); setRoutes([]); setDelegates([]);
            return;
        }
        setExpandedId(id);
        setRoutesLoading(true);
        try {
            const [routeList] = await Promise.all([getRoutes(id)]);
            setRoutes(routeList);
            loadDelegates(id);
        } catch (e) { setError(e.message); }
        finally { setRoutesLoading(false); }
    };

    const handleAddRoute = async (e) => {
        e.preventDefault();
        if (!newRouteName.trim() || !expandedId) return;
        try {
            await addRoute(expandedId, { name: newRouteName.trim() });
            setNewRouteName("");
            if (navigator.onLine) {
                setRoutes(await getRoutes(expandedId));
            } else {
                setRoutes(prev => [...prev, { id: 'pending-' + Date.now(), name: newRouteName.trim(), delegateCount: 0, checkedIn: 0, ready: false }]);
            }
        } catch (e) { setError(e.message); }
    };

    const handleUpdateRoute = async (routeId) => {
        if (!editingRouteName.trim()) return;
        try {
            await updateRoute(expandedId, routeId, { name: editingRouteName.trim() });
            setEditingRouteId(null);
            if (navigator.onLine) {
                setRoutes(await getRoutes(expandedId));
            } else {
                setRoutes(prev => prev.map(r => r.id === routeId ? { ...r, name: editingRouteName.trim() } : r));
            }
        } catch (e) { setError(e.message); }
    };

    const handleDeleteRoute = async (routeId) => {
        try {
            await deleteRoute(expandedId, routeId);
            if (navigator.onLine) {
                setRoutes(await getRoutes(expandedId));
            } else {
                setRoutes(prev => prev.filter(r => r.id !== routeId));
            }
        } catch (e) { setError(e.message); }
    };

    const handleAddDelegate = async (userIds, routeId) => {
        if (!userIds?.length || !expandedId) return;
        try {
            await addDelegate(expandedId, { userIds, routeId: routeId || undefined });
            setShowAddDelegate(false);
            if (navigator.onLine) {
                loadDelegates(expandedId);
            } else {
                const addedUsers = allUsers.filter(u => userIds.includes(u.id));
                setDelegates(prev => [
                    ...prev,
                    ...addedUsers.map(u => ({
                        id: 'pending-' + Date.now() + '-' + u.id,
                        name: u.enName,
                        badge: null,
                        userId: u.id,
                        routeId: routeId || null,
                        routeName: routeId ? (routes.find(r => r.id === routeId)?.name || null) : null,
                        routeIds: routeId ? [routeId] : [],
                        routeNames: routeId ? [(routes.find(r => r.id === routeId)?.name || null)].filter(Boolean) : [],
                        status: 'absent',
                        method: null,
                        checkedInAt: null,
                        notes: '',
                    }))
                ]);
            }
        } catch (e) { setError(e.message); }
    };

    const handleRemoveDelegate = async (delegateId) => {
        try {
            await removeDelegate(expandedId, delegateId);
            if (navigator.onLine) {
                loadDelegates(expandedId);
            } else {
                setDelegates(prev => prev.filter(d => d.id !== delegateId));
            }
        } catch (e) { setError(e.message); }
    };

    const delegateCountForRoute = (routeId) =>
        delegates.filter((d) => d.routeIds?.includes(routeId)).length;

    const openAddDelegate = async () => {
        setUsersLoading(true);
        setShowAddDelegate(true);
        try {
            const users = await getUsers();
            setAllUsers(users || []);
        } catch (e) { setError(e.message); }
        finally { setUsersLoading(false); }
    };

    const alreadyInProgramme = (userId) =>
        delegates.some((d) => d.userId === userId);

    return (
        <main className="page">
            <header className="topbar">
                <h1 className="page-title">Programmes</h1>
                {currentUser.role === 'staff' && (
                    <div className="header-actions">
                        <button className="btn btn-primary btn-sm" onClick={openCreate}>
                            <AddIcon /> New
                        </button>
                    </div>
                )}
            </header>

            {error && (
                <div className="banner banner-error mx-4 mb-3 sm:mx-auto sm:max-w-2xl">
                    <span className="min-w-0 truncate">{error}</span>
                    <button className="shrink-0 font-semibold text-bad hover:bg-white/10 rounded-lg px-2 py-1" onClick={() => setError(null)}>Dismiss</button>
                </div>
            )}

            {showForm && (
                <div className="px-4 pb-4 sm:px-6 sm:mx-auto sm:w-full sm:max-w-2xl">
                    <div className="card-pad space-y-3">
                        <h2 className="title">{editing ? "Edit Programme" : "New Programme"}</h2>
                        <div className="field">
                            <label className="field-label" htmlFor="programme-name">Programme name</label>
                            <input id="programme-name" className="input" placeholder="Programme name" value={formName} onChange={(e) => setFormName(e.target.value)} />
                        </div>
                        <div className="flex flex-col sm:flex-row gap-3">
                            <div className="field flex-1">
                                <label className="field-label" htmlFor="programme-start">Start date</label>
                                <input type="date" id="programme-start" className="input" value={formStart} onChange={(e) => setFormStart(e.target.value)} />
                            </div>
                            <div className="field flex-1">
                                <label className="field-label" htmlFor="programme-end">End date</label>
                                <input type="date" id="programme-end" className="input" value={formEnd} onChange={(e) => setFormEnd(e.target.value)} />
                            </div>
                        </div>
                        <div className="flex flex-col gap-2 pt-1 sm:flex-row">
                            <button className="btn btn-primary btn-lg btn-block sm:flex-1" onClick={handleSave}>{editing ? "Save" : "Create"}</button>
                            <button className="btn btn-secondary btn-lg btn-block sm:flex-1" onClick={() => setShowForm(false)}>Cancel</button>
                        </div>
                    </div>
                </div>
            )}

            <div className="flex-1 px-4 pb-6 sm:px-6 space-y-2 sm:mx-auto sm:w-full sm:max-w-2xl">
                {loading ? (
                    <div className="space-y-2 pt-1">
                        {[0, 1, 2].map((i) => (
                            <div key={i} className="card p-4 space-y-2">
                                <div className="skeleton-text w-2/3" />
                                <div className="skeleton-text w-1/3" />
                            </div>
                        ))}
                    </div>
                ) : !programmes || programmes.length === 0 ? (
                    <EmptyState
                        icon={<EventNote />}
                        title="No programmes"
                        desc="Create one to get started"
                        action={currentUser.role === 'staff' && (
                            <button className="btn btn-primary" onClick={openCreate}>
                                <AddIcon /> New
                            </button>
                        )}
                    />
                ) : (
                    programmes.map((p) => (
                        <div key={p.id} className="card">
                            <div className="row row-clickable" onClick={() => toggleExpand(p.id)}>
                                <div className="row-left">
                                    <div className="row-text">
                                        <span className="title truncate block">{p.name}</span>
                                        <span className="meta">{p.startDate} – {p.endDate}</span>
                                    </div>
                                </div>
                                <div className="row-actions" onClick={(e) => e.stopPropagation()}>
                                    <span className="meta whitespace-nowrap">{p.checkedIn}/{p.totalDelegates}</span>
                                    <button className="btn btn-icon text-muted hover:text-accent" onClick={() => openEdit(p)} title="Edit">
                                        <EditIcon />
                                    </button>
                                    <button className="btn btn-icon text-muted hover:text-bad hover:bg-bad-dim" onClick={() => setConfirmDelete(p.id)} title="Delete">
                                        <DeleteIcon />
                                    </button>
                                </div>
                            </div>

                            {expandedId === p.id && (
                                <div className="border-t border-edge">
                                    {/* Routes / Coaches */}
                                    <div className="px-4 py-3 bg-surface-2/40 space-y-2">
                                        <h3 className="section-title">Routes / Coaches</h3>
                                        {routesLoading ? (
                                            <div className="flex items-center justify-center py-4">
                                                <span className="spinner-sm" />
                                            </div>
                                        ) : routes.length === 0 ? (
                                            <EmptyState icon={<RouteIcon />} title="No routes yet" desc="Add one below" />
                                        ) : (
                                            <div className="space-y-1.5">
                                                {routes.map((r) => (
                                                    <div key={r.id} className="flex items-center justify-between gap-3 bg-surface-2 rounded-xl px-3 py-2.5 border border-edge">
                                                        {editingRouteId === r.id ? (
                                                            <div className="flex items-center gap-2 flex-1 min-w-0">
                                                                <input className="input flex-1 min-w-0" value={editingRouteName} onChange={(e) => setEditingRouteName(e.target.value)} autoFocus />
                                                                <button className="btn btn-sm btn-primary shrink-0" onClick={() => handleUpdateRoute(r.id)}>Save</button>
                                                                <button className="btn btn-sm btn-ghost shrink-0" onClick={() => setEditingRouteId(null)}>Cancel</button>
                                                            </div>
                                                        ) : (
                                                            <>
                                                                <div className="flex-1 min-w-0">
                                                                    <span className="row-title block">{r.name}</span>
                                                                    <span className="meta flex items-center gap-1">
                                                                        <PeopleIcon className="text-sm" />
                                                                        {delegateCountForRoute(r.id)} delegates
                                                                    </span>
                                                                </div>
                                                                <div className="flex items-center gap-1 shrink-0">
                                                                    <button className="btn btn-sm btn-primary" onClick={() => setManageRoute(r)}>Assign</button>
                                                                    <button className="btn btn-icon text-muted hover:text-accent" onClick={() => { setEditingRouteId(r.id); setEditingRouteName(r.name); }} title="Edit">
                                                                        <EditIcon />
                                                                    </button>
                                                                    <button className="btn btn-icon text-bad hover:bg-bad-dim" onClick={() => setConfirmDeleteRoute(r.id)} title="Delete">
                                                                        <DeleteIcon />
                                                                    </button>
                                                                </div>
                                                            </>
                                                        )}
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                        <form className="flex items-center gap-2 pt-1" onSubmit={handleAddRoute}>
                                            <input className="input flex-1" placeholder="New route name..." value={newRouteName} onChange={(e) => setNewRouteName(e.target.value)} />
                                            <button type="submit" className="btn btn-sm btn-primary shrink-0">Add</button>
                                        </form>
                                    </div>

                                    {/* Delegates */}
                                    <div className="border-t border-edge px-4 py-3 space-y-2">
                                        <div className="flex items-center justify-between">
                                            <h3 className="section-title">
                                                Delegates
                                                <span className="ml-1.5 normal-case font-normal text-muted">({delegates.length})</span>
                                            </h3>
                                            <button className="btn btn-sm btn-ghost" onClick={openAddDelegate}>
                                                <PersonAddIcon /> Add
                                            </button>
                                        </div>

                                        {showAddDelegate && (
                                            <div>
                                                {usersLoading ? (
                                                    <div className="flex items-center justify-center py-4">
                                                        <span className="spinner-sm" />
                                                    </div>
                                                ) : !allUsers || allUsers.length === 0 ? (
                                                    <div className="rounded-xl bg-surface-2 border border-edge p-3 text-center text-xs text-muted py-6">No users found.</div>
                                                ) : (
                                                    <UserPicker
                                                        users={allUsers}
                                                        alreadyAdded={(uid) => alreadyInProgramme(uid)}
                                                        onAdd={(userIds, routeId) => handleAddDelegate(userIds, routeId)}
                                                        onCancel={() => setShowAddDelegate(false)}
                                                        routes={routes}
                                                    />
                                                )}
                                            </div>
                                        )}

                                        {delegatesLoading ? (
                                            <div className="flex items-center justify-center py-4">
                                                <span className="spinner-sm" />
                                            </div>
                                        ) : !delegates || delegates.length === 0 ? (
                                            <EmptyState title="No delegates assigned yet" desc="Add delegates above, then assign them to routes via Manage." />
                                        ) : (
                                            <div className="space-y-1">
                                                {delegates.map((d) => (
                                                    <DelegateRow key={d.id} d={d} onRemove={setConfirmRemoveDelegate} />
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    ))
                )}
            </div>

            {manageRoute && (
                <RouteManageModal
                    route={manageRoute}
                    allDelegates={delegates}
                    programmeId={expandedId}
                    onClose={() => setManageRoute(null)}
                    onSaved={() => loadDelegates(expandedId)}
                />
            )}

            <ConfirmDialog
                open={!!confirmDelete}
                title="Delete programme?"
                message="This cannot be undone."
                confirmLabel="Delete"
                danger
                onConfirm={() => { handleDelete(confirmDelete); setConfirmDelete(null); }}
                onCancel={() => setConfirmDelete(null)}
            />

            <ConfirmDialog
                open={!!confirmDeleteRoute}
                title="Delete this route?"
                message="Delegates will keep their other routes."
                confirmLabel="Delete"
                danger
                onConfirm={() => { handleDeleteRoute(confirmDeleteRoute); setConfirmDeleteRoute(null); }}
                onCancel={() => setConfirmDeleteRoute(null)}
            />

            <ConfirmDialog
                open={!!confirmRemoveDelegate}
                title="Remove this delegate?"
                message="Remove this delegate from the programme?"
                confirmLabel="Remove"
                danger
                onConfirm={() => { handleRemoveDelegate(confirmRemoveDelegate); setConfirmRemoveDelegate(null); }}
                onCancel={() => setConfirmRemoveDelegate(null)}
            />
        </main>
    );
}
